UPDATE `creaturemodeldata` SET `size_class` = 4, `model_scale` = 1, `collision_width` = 0.6111, `collision_height` = 2.031, `mount_height` = 4.54894, `geo_box_min_x` = -1.13172, `geo_box_min_y` = -1.85276, `geo_box_min_z` = -0.020017, `geo_box_max_x` = 1.21447, `geo_box_max_y` = 1.14106, `geo_box_max_z` = 7.3365, `world_effect_scale` = 1, `attached_effect_scale` = 1, `missile_collision_radius` = 0, `missile_collision_push` = 0, `missile_collision_raise` = 0 WHERE `id` = @TitanMaleModel;
